import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep, vec2, fract, sin, dot, float, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, DirectionalLight } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'pricing-card-1';

  const innerGroup = new Group();
  root.add(innerGroup);

  // --- Atlas region aspect (512x320) ---
  const atlasAspect = 512 / 320;
  const spriteWidth = 2.0;
  const spriteHeight = spriteWidth / atlasAspect;

  const cardWidth = spriteWidth + 0.3;
  const cardHeight = spriteHeight + 0.3;

  // ---- Backing card panel: machined-metal PBR w/ engineered gradient + subtle grain ----
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight, 1, 1);
  const cardMat = new MeshPhysicalNodeMaterial({
    roughness: 0.55,
    metalness: 0.4,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
    side: THREE.FrontSide,
  });

  const uvN = uv();
  const gradient = mix(color(colors.ink), color(colors.surface), smoothstep(0.0, 1.0, uvN.y));
  const grainSeed = dot(uvN.mul(400.0), vec2(12.9898, 78.233));
  const grain = fract(sin(grainSeed).mul(43758.5453)).mul(0.035);
  cardMat.colorNode = gradient.add(grain);

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.z = -0.03;
  innerGroup.add(cardMesh);

  // ---- Contact / depth shadow plane behind card ----
  const shadowGeo = new PlaneGeometry(cardWidth * 1.35, cardHeight * 1.35, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  const shUv = uv();
  const dist = length(shUv.sub(vec2(0.5, 0.5)));
  const fade = smoothstep(0.5, 0.1, dist);
  shadowMat.colorNode = color(colors.surface);
  shadowMat.opacityNode = fade.mul(0.5);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.z = -0.08;
  innerGroup.add(shadowMesh);

  // ---- Sprite plane carrying floating-accent image ----
  const spriteGeo = new PlaneGeometry(spriteWidth, spriteHeight, 1, 1);
  const spriteMat = new MeshBasicNodeMaterial({ transparent: true });
  const spriteMesh = new Mesh(spriteGeo, spriteMat);
  spriteMesh.position.z = 0.03;
  innerGroup.add(spriteMesh);

  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      spriteMat.map = tex;
      spriteMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- Node-local rim/accent light (back-lit edge, does not fight the global key) ----
  const rimLight = new DirectionalLight(new THREE.Color(colors.accent), 0.55);
  rimLight.position.set(-1.2, -0.8, -1.4);
  innerGroup.add(rimLight);

  // ---- Text content (bridging idiom) — none for this node, loop is a no-op ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item?.text) continue;
    const t = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 24,
      color: colors.paper,
      align: 'left',
    });
    innerGroup.add(t);
  }

  // ---- Cinematic primitives (spec ships none — loop is inert) ----
  const primitiveHandles = [];
  const primList = config.cinematicPrimitives ?? [];
  for (const prim of primList) {
    if (ctx.primitives?.[prim.name]) {
      const handle = ctx.primitives[prim.name](innerGroup, prim.params ?? {});
      primitiveHandles.push(handle);
    }
  }

  // ---- Motion: weighted-settle entrance + subtle breathing idle (static composition, no interactivity) ----
  innerGroup.scale.setScalar(0.96);
  innerGroup.position.y = 0.3;

  const timeline = gsap.timeline();
  timeline.to(innerGroup.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  });
  timeline.to(innerGroup.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  }, 0);

  const breathe = gsap.to(innerGroup.scale, {
    x: 1.015,
    y: 1.015,
    z: 1.015,
    duration: 4.5,
    ease: 'sine.inOut',
    yoyo: true,
    repeat: -1,
    delay: 0.9,
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timeline.kill();
    breathe.kill();
    for (const h of primitiveHandles) {
      h?.timeline?.kill?.();
      h?.cleanup?.();
    }

    cardGeo.dispose();
    cardMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    spriteGeo.dispose();
    spriteMat.dispose();

    if (loadedTexture) {
      loadedTexture.dispose();
    }

    innerGroup.remove(rimLight);
    innerGroup.clear();
    root.clear();
  };

  return root;
}
